const BASE = "https://api.lokalise.com/api2";
const PID = "31393214664f295f94dd86.76792605";
const TOTAL = 17522, LIMIT = 200;
const out = [];
for (let p = 1; p <= Math.ceil(TOTAL / LIMIT); p++) {
  out.push({ json: { page: p, url: BASE + "/projects/" + PID + "/keys?limit=" + LIMIT + "&page=" + p
    + "&include_translations=1&filter_translation_lang_ids=640" } });
}
return out;

// PERSO-3766: country-level legal compliance content on checkout.
// Buckets are reported separately so the tag scope can be chosen deliberately.
const KEYNAME = {
  checkout: /(checkout|payment|billing|purchase|order|cart|upsell|paywall|pricing|plan)/i,
  legal: /(terms|privacy|policy|consent|cookie|disclaimer|gdpr|refund|cancel|subscription|renewal|guarantee|compliance|legal|imprint)/i
};
const SOURCE = /(disclaimer|consent|GDPR|FTC|terms of use|privacy policy|refund|auto-renew|automatically renew|cancel anytime|money-?back|guarantee|billed|subscription will|recurring|you agree|by continuing|by clicking)/i;

const items = $input.all();
const buckets = { checkout_and_legal: [], checkout_only: [], legal_only: [], source_only: [] };
const errors = [];
let seen = 0;
for (const it of items) {
  const r = it.json || {};
  const b = r.body !== undefined ? r.body : r;
  if (!Array.isArray(b.keys)) { errors.push({ status: r.statusCode }); continue; }
  for (const k of b.keys) {
    if (k.is_archived) continue;
    seen++;
    const kn = (k.key_name && (k.key_name.web || k.key_name.other)) || '';
    if (!kn) continue;
    let en = '';
    for (const t of (k.translations || [])) if (t.language_iso === 'en') en = t.translation || '';
    const hasCheckout = KEYNAME.checkout.test(kn);
    const hasLegal = KEYNAME.legal.test(kn);
    const hasSource = SOURCE.test(en);
    const row = { id: k.key_id, k: kn, en: String(en).slice(0, 120), tags: k.tags || [] };
    if (hasCheckout && (hasLegal || hasSource)) buckets.checkout_and_legal.push(row);
    else if (hasCheckout) buckets.checkout_only.push(row);
    else if (hasLegal) buckets.legal_only.push(row);
    else if (hasSource) buckets.source_only.push(row);
  }
}
const counts = {};
for (const n of Object.keys(buckets)) counts[n] = buckets[n].length;
// existing tags in the project, so we can see whether epic-key tagging is already a convention
const tagCount = {};
for (const n of Object.keys(buckets)) for (const r of buckets[n]) for (const t of r.tags) tagCount[t] = (tagCount[t] || 0) + 1;
return [{ json: {
  pages: items.length, errors: errors, keys_seen: seen,
  counts: counts,
  existing_tags_on_candidates: Object.entries(tagCount).sort((a, b2) => b2[1] - a[1]).slice(0, 25),
  checkout_and_legal: buckets.checkout_and_legal.slice(0, 60),
  checkout_only: buckets.checkout_only.slice(0, 30),
  legal_only: buckets.legal_only.slice(0, 30),
  source_only: buckets.source_only.slice(0, 30)
} }];
